"""Meridian CRM RBAC permission check migration."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform an action on a record."""
    user_role = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    # Permission rows are evaluated in supplied order.  A missing row denies.
    matching_row = None
    for row in role_rows:
        if (
            row.get("role_id", "") == user_role
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_row = row
            break

    if matching_row is None:
        return False

    # DELETE is subject to the soft-deletable row-level rule for every role.
    if action == "DELETE" and record.get("DEL_FLG", "") == "Y":
        return False

    # ADMIN bypasses scope only; the matching permission row is still required.
    if user_role == "ADMIN":
        return True

    scope = matching_row.get("scope", "")

    if scope == "ALL":
        return True
    if scope == "TEAM":
        return user_team == record.get("TEAM_CD", "")
    if scope == "OWN":
        return user_id == record.get("OWNER_UID", "")
    if scope == "NONE":
        return False

    return False
